    /**     * 唯一的 upcall：围栏回调跳板。native 从它自己的 worker std::thread 调用，     * JVM 对此一无所知，所以这两个字段必须是静态的并活到进程结束——被回收的     * upcall stub 就是一个悬空函数指针。异常逃出 upcall 目标会直接终止 JVM，     * 因此 [onFenceComplete] 自己吞掉 Throwable，不依赖 catchException 包装。     */
    private var STUB_TARGET: MethodHandle? = null
    private var FENCE_STUB: MemorySegment? = null
    init {
        var lib: SymbolLookup? = null
        var failure: Throwable? = null
        try {
            val dllPath = extractLibrary()
            lib = SymbolLookup.libraryLookup(dllPath, ARENA)
        } catch (t: Throwable) {
            failure = t
        }
        val loaded = lib
        if (loaded == null) {
            LIB = null
            LOAD_FAILURE = failure
        } else {
            LIB = loaded
            var bindFailure: Throwable? = null
            try {
                bindAll()
                verifyABI()
            } catch (t: Throwable) {
                bindFailure = t
            }
            LOAD_FAILURE = bindFailure
            if (bindFailure == null) {
                println(
                    "[backend] MCDR native library loaded (FFM): ${LIB_NAME}"
                            + ", ABI v${safeABIVersion()}"
                )
                println("[backend] struct layouts: ${MCDRLayout.describeSizes()}")
                println(
                    "[backend] 启动日志级别 ${IllusionLogger.level()}"
                            + "（配置加载前；生效级别由 config/dxr_mc-client.toml 的 [logging] logLevel 决定，"
                            + "加载后会另行打印一行；开发时可用环境变量 DX12_LOG_VERBOSE=1 强制 DEBUG）"
                )
            }
        }
    }
    // ==================================================================
    // Loading
    // ==================================================================
    private fun safeABIVersion(): Int {
        return try {
            MH_abiversion!!.invokeExact() as Int
        } catch (t: Throwable) {
            -1
        }
    }
    /**     * Copy MCDR.dll out of the mod JAR to `<user.dir>/dxrmc/` and return the     * path. The local copy is refreshed whenever its bytes differ from the JAR resource —     * a byte-for-byte comparison rather than the original "local mtime newer && same size"     * test, because JAR entry timestamps are pinned to the 1980 epoch and two different     * DLLs can share a size, which once let a stale local copy shadow a new build.     *     * <p>If the resource is absent (the JVM and native repos are separate, so a build may     * legitimately ship without a DLL) an already-extracted local file is used as-is.     */
    private fun extractLibrary(): Path {
        val dir = Path.of(System.getProperty("user.dir"), EXTRACT_DIR)
        Files.createDirectories(dir)
        extractVendorResources(dir)
        val dllPath = dir.resolve(LIB_NAME)
        var useJarDll = true
        var jarBytes: ByteArray? = null
        try {
            MCDR_ABI::class.java.getResourceAsStream("/${LIB_NAME}").use { input ->
                if (input != null) {
                    jarBytes = input.readAllBytes()
                }
            }
        } catch (ignored: Exception) {
            // fall through: treat as "not packaged"
        }
        if (jarBytes == null) {
            if (!Files.exists(dllPath)) {
                throw IllegalStateException("${LIB_NAME} is neither packaged in the JAR nor present at "
                    + "${dllPath.toAbsolutePath()} — build the MCDR native project first")
            }
            useJarDll = false
        } else if (Files.exists(dllPath)) {
            try {
                if (jarBytes.contentEquals(Files.readAllBytes(dllPath))) {
                    useJarDll = false
                }
            } catch (ignored: Exception) {
                // unreadable local copy -> overwrite it
            }
        }
        if (useJarDll) {
            Files.write(dllPath, jarBytes!!)
        }
        return dllPath.toAbsolutePath()
    }
    /**     * Unpack the bundled SDK runtimes into [dir] (the folder MCDR.dll is extracted to).     *     * <p>Same refresh rule as [extractLibrary], and for the same reason: a byte comparison,     * not a timestamp one. These files are 13–78 MB each, so the content check is what keeps a     * normal launch cheap — an unchanged file costs one read. It is also the difference from     * blindly overwriting: a JAR whose contents never change would otherwise rewrite ~176 MB     * on every single start-up.     *     * <p>Never throws. These SDKs are optional: a missing or unreadable resource, a read-only     * `dxrmc/`, or a disk error must degrade to "that SDK reports itself unavailable", never to     * a failed mod start.     */
    private fun extractVendorResources(dir: Path) {
        try {
            val entries = javaClass.getResourceAsStream(VENDOR_MANIFEST)?.use { input ->
                input.readAllBytes().toString(Charsets.UTF_8)
                    .lineSequence()
                    .map { it.trim() }
                    .filter { it.isNotEmpty() && !it.startsWith("#") }
                    .toList()
            } ?: return
            var written = 0
            var current = 0
            val problems = mutableListOf<String>()
            for (entry in entries) {
                try {
                    val bytes = javaClass.getResourceAsStream("/$entry")?.use { it.readAllBytes() }
                    if (bytes == null) {
                        problems += "$entry (未打进 JAR)"
                        continue
                    }
                    val target = dir.resolve(entry.substringAfterLast('/'))
                    // A licence entry is intentionally named "LICENSE-xess.txt" (dash) while its
                    // source is "LICENSE.txt"; everything else keeps its packaged name.
                    if (Files.exists(target)) {
                        val same = try {
                            Files.readAllBytes(target).contentEquals(bytes)
                        } catch (ignored: Exception) {
                            false
                        }
                        if (same) {
                            current++
                            continue
                        }
                    }
                    Files.write(target, bytes)
                    written++
                } catch (t: Throwable) {
                    problems += "$entry (${t.message ?: t::class.java.simpleName})"
                }
            }
            if (written > 0 || problems.isNotEmpty()) {
                println("[backend] SDK 运行库：解出 $written 个、已最新 $current 个"
                    + (if (problems.isEmpty()) "" else "，失败 ${problems.size} 个：${problems.joinToString("; ")}"))
            }
        } catch (ignored: Throwable) {
            // No manifest (the JVM repo does not build the native SDKs), or an unreadable
            // resource stream: the SDKs are optional, so stay silent rather than fail start-up.
        }
    }
    private fun requireLoaded() {
        if (LOAD_FAILURE != null) {
            throw IllegalStateException("MCDR native library is unavailable: ${LOAD_FAILURE}", LOAD_FAILURE)
        }
    }
    /** True when the library loaded, bound and its layout self-check passed. */
    fun isAvailable(): Boolean {
        return LOAD_FAILURE == null
    }
    /** Why the library is unavailable, or null when it is fine. */
    fun unavailableReason(): String? {
        return LOAD_FAILURE?.toString()
    }
    private fun skip(name: String, desc: FunctionDescriptor): MethodHandle {
        val addr = LIB!!.find(name).orElseThrow {
            IllegalStateException("MCDR export not found: ${name}")
        }
        return LINKER.downcallHandle(addr, desc)
    }
    /**     * Like [skip], but tolerates an export the loaded DLL does not have: returns null instead of     * failing the whole bind. Used for exports added after the ABI was frozen, so a stale     * `MCDR.dll` degrades one feature instead of killing start-up.     */
    private fun skipOptional(name: String, desc: FunctionDescriptor): MethodHandle? {
        return try {
            val addr = LIB!!.find(name).orElse(null) ?: return null
            LINKER.downcallHandle(addr, desc)
        } catch (t: Throwable) {
            null
        }
    }
    private fun fd(ret: MemoryLayout, vararg args: MemoryLayout): FunctionDescriptor {
        return FunctionDescriptor.of(ret, *args)
    }
    private fun fdv(vararg args: MemoryLayout): FunctionDescriptor {
        return FunctionDescriptor.ofVoid(*args)
    }
    /** Cross-check every mirrored struct offset/size against the running DLL. */
    private fun verifyABI() {
        val version = MH_abiversion!!.invokeExact() as Int
        if (version != MCDR_ABI_VERSION) {
            throw IllegalStateException("MCDR ABI version mismatch: java=${MCDR_ABI_VERSION}, native=${version}")
        }
        Arena.ofConfined().use { arena ->
            val pFields = arena.allocate(MCDRLayout.PTR)
            val pCount = arena.allocate(MCDRLayout.I32)
            MH_abilayout!!.invokeExact(pFields, pCount)
            val count = pCount.get(MCDRLayout.I32, 0)
            val first = pFields.get(MCDRLayout.PTR, 0) as MemorySegment
            if (count <= 0 || first.address() == 0L) {
                throw IllegalStateException("mcdrABILayout() reported ${count} fields")
            }
            val fields = first.reinterpret(MCDRLayout.ABI_FIELD.byteSize() * count)
            val nativeFields = mutableMapOf<String, LongArray>()
            val stride = MCDRLayout.ABI_FIELD.byteSize()
            for (i in 0 until count) {
                val f = fields.asSlice(i * stride, stride)
                val nameSeg = f.get(MCDRLayout.PTR, 0) as MemorySegment
                val name = nameSeg.reinterpret(Long.MAX_VALUE).getString(0)
                nativeFields[name] = longArrayOf(f.get(MCDRLayout.I64, 8) as Long, f.get(MCDRLayout.I64, 16) as Long)
            }
            MCDRLayout.verify(nativeFields)
        }
    }
    private fun unexpected(t: Throwable): RuntimeException {
        return IllegalStateException("MCDR native call failed: ${t}", t)
    }
    private fun ptr(handle: Long): MemorySegment {
        return MemorySegment.ofAddress(handle)
    }
    private fun addr(seg: MemorySegment?): Long {
        return if (seg == null) 0L else seg.address()
    }
    /** `MCDR_ABI_VERSION` from `mcdr_abi.h`. */
    const val MCDR_ABI_VERSION: Int = 2
    /** Return value of a native "bool" (declared `int32_t`) as a Java boolean. */
    private fun ok(value: Int): Boolean {
        return value != 0
    }
    // ==================================================================
    // Per-thread scratch slots.
    //
    // A thread owns four reusable buffers, each backed by its own arena so that growing one
    // never invalidates another. This replaces the JNI bridge's per-call Get*ArrayElements /
    // new[] pairs on the core hot path: after the first few frames the native calls perform
    // no allocation at all.
    // ==================================================================
    private const val SLOT_COUNT = 4
    private val SCRATCH: ThreadLocal<Scratch> = ThreadLocal.withInitial { Scratch() }
    private class Scratch {
        private val arenas = arrayOfNulls<Arena>(SLOT_COUNT)
        private val segments = arrayOfNulls<MemorySegment>(SLOT_COUNT)
        init {
            for (i in 0 until SLOT_COUNT) {
                arenas[i] = Arena.ofConfined()
                segments[i] = MemorySegment.NULL
            }
        }
        fun slot(index: Int, bytes: Long): MemorySegment {
            val need = bytes.coerceAtLeast(8L)
            val segments = this.segments
            if (segments[index]!!.byteSize() < need) {
                arenas[index]!!.close()
                arenas[index] = Arena.ofConfined()
                segments[index] = arenas[index]!!.allocate(need, 16L)
            }
            return segments[index]!!
        }
    }
    private fun scratch(index: Int, bytes: Long): MemorySegment {
        return SCRATCH.get().slot(index, bytes)
    }
    // ==================================================================
    // Meta
    // ==================================================================
    /** Last error message recorded by any native entry point on the calling thread; "" if none. */
    fun D3D12LastError(): String {
        requireLoaded()
        Arena.ofConfined().use { arena ->
            val need = MH_lasterror!!.invokeExact(MemorySegment.NULL, 0) as Int
            if (need <= 0) {
                return ""
            }
            val buf = arena.allocate(need.toLong())
            val written = MH_lasterror!!.invokeExact(buf, need) as Int
            return if (written > 0) buf.getString(0) else ""
        }
    }
    /** Route native log output through `DEBUG` (1) or `verbose` (0). */
    fun D3D12SetLogVerbose(enabled: Boolean) {
        if (LOAD_FAILURE != null) {
            return
        }
        try {
            MH_setlogverbose!!.invokeExact(if (enabled) 1 else 0)
        } catch (ignored: Throwable) {
            // logging configuration must never fail engine start-up
        }
    }
    /**     * Push the configured native log level (0 = error, 1 = warning, 2 = info, 3 = debug) into     * the DLL. Falls back to [D3D12SetLogVerbose] when the loaded DLL predates     * `mcdrSetLogLevel` (it treats "2 and above" as the old verbose-on).     *     * <p>Called by [IllusionLogger] before the device is created, which is the order the     * native side expects — it no longer reads `DX12_LOG_VERBOSE` from the environment itself.     */
    fun D3D12SetLogLevel(level: Int) {
        if (LOAD_FAILURE != null) {
            return
        }
        val clamped = level.coerceIn(0, 3)
        try {
            val handle = MH_setloglevel
            if (handle != null) {
                handle.invokeExact(clamped)
            } else {
                D3D12SetLogVerbose(clamped >= 2)
            }
        } catch (ignored: Throwable) {
            // logging configuration must never fail engine start-up
        }
    }
    /**     * Set one process-wide environment variable, or clear it when [value] is null.     *     * <p>The configuration is the single place users look; a few native switches are still     * read with `getenv`, so this pushes the configured value into the process right before the     * device is created. Optional export: an older DLL simply ignores the call.     */
    fun D3D12SetEnvironment(name: String, value: String?) {
        if (LOAD_FAILURE != null) {
            return
        }
        val handle = MH_setenvironment ?: return
        try {
            Arena.ofConfined().use { arena ->
                val key = cstringUtf8(arena, name)
                val valSeg = if (value == null) MemorySegment.NULL else cstringUtf8(arena, value)
                handle.invokeExact(key, valSeg)
            }
        } catch (ignored: Throwable) {
            // configuration propagation must never fail start-up
        }
    }
    /**     * Load Microsoft PIX's GPU capture layer (`WinPixGpuCapturer.dll`) into this process.     *     * <p>PIX hooks Direct3D 12 from inside that DLL, so it has to be in place **before the first     * device is created**. That is why [dev.nts.expdxr.Illusion] pushes this value as soon as the     * config file is read, and why the options is marked "restart required".     *     * @return 1 when the layer is loaded, 0 when capture was not requested, -1 when it was     *     requested but the DLL could not be found or loaded, and [Int.MIN_VALUE] when the loaded     *     native DLL predates this export. Never throws: a diagnostic must not break startup.     */
    fun D3D12SetPIXCapture(enabled: Boolean): Int {
        if (LOAD_FAILURE != null) {
            return Int.MIN_VALUE
        }
        val handle = MH_setpixcapture ?: return Int.MIN_VALUE
        return try {
            val status = handle.invokeExact(if (enabled) 1 else 0) as Int
            status
        } catch (t: Throwable) {
            System.err.println("[backend-java] dx12SetPixCapture failed: $t")
            Int.MIN_VALUE
        }
    }
    /**     * Tell native where PIX's DLLs are (`[debug] pixDirectory`): the DLL itself, or the directory     * holding them. Call it before [D3D12SetPIXCapture] — the capture layer has to be loaded     * before the first D3D12 device exists, so the path has to be known that early.     *     * <p>An empty path clears the setting and restores automatic detection (next to MCDR.dll,     * then the newest `%ProgramFiles%\\Microsoft PIX\\<version>`).     *     * @return 1 when the path was accepted, 0 when it was cleared, -1 when it is not valid UTF-8     *     or does not exist (native logs the details), and [Int.MIN_VALUE] when the loaded native     *     DLL predates this export.     */
