            return Int.MIN_VALUE
        }
        val handle = MH_setpixdirectory ?: return Int.MIN_VALUE
        return try {
            Arena.ofConfined().use { arena ->
                val status = handle.invokeExact(cstringUtf8(arena, path)) as Int
                status
            }
        } catch (t: Throwable) {
