    /**     * Start a PIX *timing* capture and have PIX write it to [path] (`.wpix`).     *     * <p>This is the one capture PIX's own UI cannot produce for us: its continuous ("counters")     * recording keeps everything inside the PIX session, and a GPU capture taken by attaching     * lands in `%TEMP%`. Only PIXBeginCapture, called by the process itself, writes a file where     * the caller asks. `path` is a UTF-8 full path; the caller creates the directory.     *     * <p>The native side calls PIX on a thread of its own (the render thread's COM apartment is     * already fixed, and PIXBeginCapture answers `RPC_E_CHANGED_MODE` from it) and waits up to     * ten seconds for the answer.     *     * @return 1 when the capture started, 0 when one was already running, and on failure the     *     HRESULT that explains it (always negative), meant to be shown to the player as-is:     *     `E_ACCESSDENIED` (0x80070005) means the process is not elevated — measured here, the     *     `Performance Log Users` group is *not* enough on this machine, whatever PIX's docs say     *     — and `ERROR_ALREADY_EXISTS` (0x800700B7) means a capture session from an earlier run     *     is still alive. `Int.MIN_VALUE` means the loaded DLL predates this export.     */
    fun D3D12StartPIXTimingCapture(path: String): Int {
        if (LOAD_FAILURE != null) {
            return Int.MIN_VALUE
        }
        val handle = MH_startpixtiming ?: return Int.MIN_VALUE
        return try {
            Arena.ofConfined().use { arena ->
                val status = handle.invokeExact(cstringUtf8(arena, path)) as Int
                status
            }
        } catch (t: Throwable) {
            System.err.println("[backend-java] mcdrStartPixTimingCapture failed: $t")
            Int.MIN_VALUE
        }
    }
    /**     * Stop the capture [D3D12StartPIXTimingCapture] started and let PIX write the file out.     *     * <p>Returns without waiting: PIX spools the file on its own thread, and a capture with the     * memory events on is hundreds of megabytes — blocking the frame that stops it would stall     * the game.     *     * @return 1 when a stop was requested, 0 when nothing was recording, and a negative     *     HRESULT when PIX's stop entry point could not be reached or the writer thread could     *     not be started, `Int.MIN_VALUE` when the loaded DLL predates this export.     */
