    /**     * Map a buffer region and return a view of the mapped memory.     *     * <p>The returned buffer is set to [ByteOrder.nativeOrder] (LITTLE_ENDIAN on     * Windows x64). The JNI original handed back a `NewDirectByteBuffer`, which Java     * defines as BIG_ENDIAN and which silently corrupted every UBO matrix until P26 — the     * order is now explicit at the boundary as well as declarative in the layouts.     *     * @return the mapped view, or null on failure (see [D3D12LastError])     */
    fun D3D12MapBuffer(bufferHandle: Long, offset: Long, length: Long,
                       read: Boolean, write: Boolean): ByteBuffer? {
        requireLoaded()
        Arena.ofConfined().use { arena ->
            val pLen = arena.allocate(MCDRLayout.I64)
            val base = MH_mapbuffer!!.invokeExact(
                ptr(bufferHandle), offset, length, if (read) 1 else 0, if (write) 1 else 0, pLen) as MemorySegment
            if (base.address() == 0L) {
                return null
            }
            val actual = pLen.get(MCDRLayout.I64, 0) as Long
            return base.reinterpret(actual).asByteBuffer().order(ByteOrder.nativeOrder())
        }
    }
