    /**     * P57: fold one worker partition's per-core sequence — write the descriptors, take the     * GPU handle, set the root table, bind the index and vertex buffers, DrawIndexedInstanced(1)     * — into a single native call.     *     * <p>The 14 parallel arrays are still accepted (so the callers port unchanged) but are     * repacked once into the [MCDRLayout.BINDING_SLOT] and     * [MCDRLayout.PARTITION_DRAW] struct arrays the ABI actually takes. The descriptor value     * arrays are indexed by the <em>global</em> core `d = startDraw + i` as `arr[d*bc + j]`,     * matching the JNI original; `bType` is one entry per binding slot (length `bc`). The     * native side receives only this partition's slice.     */
    fun AsyncBundleRecordPartition(alloc: Long, pool: Long, worker: Int,
                                   baseSlot: Int, bc: Int, startDraw: Int, count: Int,
                                   bType: IntArray,
                                   bBuf: LongArray, bOff: LongArray, bLen: LongArray, bView: LongArray,
                                   idxBuf: LongArray, idxType: IntArray, idxCount: IntArray, firstIdx: IntArray, baseVert: IntArray,
                                   vbSlot: IntArray, vbBuf: LongArray, vbOff: LongArray, vbStride: IntArray): Boolean {
        return recordPartition(false, alloc, pool, worker, baseSlot, bc, startDraw, count,
            bType, bBuf, bOff, bLen, bView,
            idxBuf, idxType, idxCount, firstIdx, baseVert,
            vbSlot, vbBuf, vbOff, vbStride)
