    /** Non-blocking: has the fence reached `value`? */
    fun D3D12AsyncFenceIsComplete(mgr: Long, value: Long): Boolean {
        requireLoaded()
        try {
            return ok(MH_asyncfenceiscomplete!!.invokeExact(ptr(mgr), value) as Int)
        } catch (t: Throwable) {
