    /**     * Builds the single upcall stub this library needs: the fence-callback trampoline.     *     * <p>Native invokes it from a worker `std::thread` the JVM knows nothing about, so     * the stub lives in the shared [ARENA] and is referenced from [FENCE_STUB]     * for the process lifetime — a collected stub is a dangling function pointer. An     * exception escaping an upcall target terminates the JVM abruptly, which is why     * `onFenceComplete` catches [Throwable] itself rather than trusting a     * `catchException` wrapper.     */
    private fun bindFenceStub() {
        try {
            STUB_TARGET = MethodHandles.lookup().findStatic(MCDR_ABI::class.java, "onFenceComplete",
                MethodType.methodType(Void.TYPE, Long::class.javaPrimitiveType, Long::class.javaPrimitiveType, Int::class.javaPrimitiveType))
        } catch (e: ReflectiveOperationException) {
            throw IllegalStateException("cannot resolve the fence upcall target", e)
        }
        FENCE_STUB = LINKER.upcallStub(STUB_TARGET!!, fdv(MCDRLayout.I64, MCDRLayout.I64, MCDRLayout.I32), ARENA)
    }
